#include "animation_layer_export.h"
#include "webp_export.h"
#include <windows.h>
#include <set>
namespace moon {
std::vector<std::string> animationExportLayerIds(const timeline::State& state,const std::string& requested){for(const auto& layer:state.layers)if(layer.id==requested)return {requested};std::vector<std::string> result;for(auto layer=state.layers.rbegin();layer!=state.layers.rend();++layer)result.push_back(layer->id);return result;}
static std::optional<AnimationLayerExportPlan> planLayerExport(const Document& d,const std::string& requested,const std::filesystem::path& directory,std::u32string name,std::u32string extension,const ExportConflictResolver& resolve){AnimationLayerExportPlan out;out.layerIds=animationExportLayerIds(d.timeline().state(),requested);name=framePngExportStem(std::move(name));std::set<std::wstring> used;for(std::size_t i=0;i<out.layerIds.size();++i){const auto& layer=d.timeline().state().layers[d.timeline().layerIndex(out.layerIds[i])];auto n=std::to_string(i+1);const auto base=name+U"-"+framePngExportStem(layer.name,U"layer-"+std::u32string(n.begin(),n.end()));auto stem=base;for(int duplicate=2;;++duplicate){auto key=std::filesystem::path(stem).wstring();CharLowerBuffW(key.data(),DWORD(key.size()));if(used.insert(key).second)break;auto number=std::to_string(duplicate);stem=base+U"-"+std::u32string(number.begin(),number.end());}out.paths.push_back(directory/std::filesystem::path(stem+extension));}auto paths=resolveExportDestinations(std::move(out.paths),resolve);if(!paths)return {};out.paths=std::move(*paths);return out;}
std::optional<AnimationLayerExportPlan> planAnimationLayerExport(const Document& d,const std::string& id,const std::filesystem::path& directory,std::u32string name,bool webp,const ExportConflictResolver& resolve){return planLayerExport(d,id,directory,std::move(name),webp?U".webp":U".gif",resolve);}
std::optional<AnimationLayerExportPlan> planStaticLayerExport(const Document& d,const std::string& id,const std::filesystem::path& directory,std::u32string name,int format,const ExportConflictResolver& resolve){if(format<0||format>5)throw std::invalid_argument("Static layer export format unavailable");return planLayerExport(d,id,directory,std::move(name),format==5?U".jpg":format==3?U".svg":format==2?U".ico":format==1?U".bmp":U".png",resolve);}
std::optional<AnimationLayerExportPlan> planSliceExport(const Document& d,const std::string& requested,const std::filesystem::path& directory,std::u32string extension,const ExportConflictResolver& resolve){if(d.slices().empty())throw std::invalid_argument("No slices to export");AnimationLayerExportPlan out;std::set<std::wstring> used;for(const auto& s:d.slices()){if(!requested.empty()&&s.id!=requested)continue;const auto base=sanitizeSliceName(s.name);auto stem=base;for(int duplicate=2;;++duplicate){auto key=std::filesystem::path(stem).wstring();CharLowerBuffW(key.data(),DWORD(key.size()));if(used.insert(key).second)break;const auto n=std::to_string(duplicate);stem=base+U"-"+std::u32string(n.begin(),n.end());}out.layerIds.push_back("slice:"+s.id);out.paths.push_back(directory/std::filesystem::path(stem+extension));}if(out.paths.empty())throw std::invalid_argument("Slice export target unavailable");auto paths=resolveExportDestinations(std::move(out.paths),resolve);if(!paths)return {};out.paths=std::move(*paths);return out;}
std::size_t writeAnimationLayerExport(const Document& d,const AnimationLayerExportOptions& settings,const AnimationLayerExportPlan& plan,const std::function<bool()>& cancelled,const std::function<void(std::size_t,std::size_t)>& progress){if(plan.layerIds.size()!=plan.paths.size())throw std::invalid_argument("Layer export destination count mismatch");std::size_t written=0;for(std::size_t i=0;i<plan.layerIds.size();++i){if(cancelled&&cancelled())break;const bool slice=plan.layerIds[i].rfind("slice:",0)==0;const auto target=slice?plan.layerIds[i].substr(6):plan.layerIds[i];if(!slice&&!d.timeline().hasLayer(target))throw std::invalid_argument("Layer export snapshot target unavailable");auto options=settings.animation;options.layerId=slice?std::string{}:target;options.sliceId=slice?target:std::string{};options.selection=false;std::vector<std::uint8_t> bytes;if(settings.staticImage){auto image=settings.image;image.layerId=slice?std::string{}:target;image.sliceId=slice?target:std::string{};image.selection=false;image.automatic=settings.format==4;if(settings.format==5)bytes=encodeStaticImageJpeg(d,image).bytes;else if(settings.format==3)bytes=encodeStaticImageSvg(d,image).bytes;else if(settings.format==2)bytes=encodeStaticImageIco(d,image).bytes;else if(settings.format==1)bytes=encodeStaticImageBmp(d,image).bytes;else if(settings.format==0||settings.format==4)bytes=encodeStaticImagePng(d,image).png;else throw std::invalid_argument("Static layer export format unavailable");}else bytes=(settings.webp?encodeAnimationWebp(d,options):encodeAnimationGif(d,options)).bytes;if(cancelled&&cancelled())break;writeExportBytesAtomic(plan.paths[i],bytes);++written;if(progress)progress(written,plan.paths.size());if(cancelled&&cancelled())break;}return written;}
}
